declare(strict_types=1);

/**
 * GET api/stats.php?hours=24
 *
 * Returns min / avg / max for every measure column over the last N hours.
 * The window start is computed in PHP and bound as a plain DATETIME, which
 * keeps the index on `measured_at` usable and avoids placeholders inside an
 * INTERVAL expression.
 */

require __DIR__ . '/bootstrap.php';

$hours = query_int('hours', 24, 1, PI_SENSOR_MAX_HOURS);

// Reference clock comes from the database, see db_since().
$since = db_since($hours);

$columns = [];
foreach (PI_SENSOR_FIELDS as $field) {
    $columns[] = "MIN({$field}) AS min_{$field}";
    $columns[] = "AVG({$field}) AS avg_{$field}";
    $columns[] = "MAX({$field}) AS max_{$field}";
}

$sql = 'SELECT COUNT(*) AS row_count, ' . implode(",\n           ", $columns) . '
          FROM measurements
         WHERE measured_at >= ?';

try {
    $statement = db()->prepare($sql);
    $statement->bindValue(1, $since, PDO::PARAM_STR);
    $statement->execute();
    $row = $statement->fetch();
} catch (PDOException $e) {
    error_log('pi_sensor: stats query failed: ' . $e->getMessage());
    json_error('Abfrage fehlgeschlagen', 503);
}

$stats = [];
foreach (PI_SENSOR_FIELDS as $field) {
    $stats[$field] = [
        'min' => round_or_null($row["min_{$field}"] ?? null),
        'avg' => round_or_null($row["avg_{$field}"] ?? null),
        'max' => round_or_null($row["max_{$field}"] ?? null),
    ];
}

json_out([
    'hours' => $hours,
    'rows' => (int) ($row['row_count'] ?? 0),
    'stats' => $stats,
], 200, 30);
